// LOCAL DEV FALLBACK ONLY. Same TPC-DS schema as Zetaris' TPCDS_DB sample,
// generated by `npm run seed:local`. Receipts are labeled "local-dev" so a
// local run can never be mistaken for the Zetaris demo.
import { DuckDBInstance, type DuckDBConnection } from "@duckdb/node-api";
import { assertReadOnly, type QueryResult, type SqlBackend } from "./backend.ts";

export class LocalBackend implements SqlBackend {
  name = "local-dev (DuckDB TPC-DS, not Zetaris)";
  isZetaris = false;
  private conn?: Promise<DuckDBConnection>;

  t(table: string) {
    return table;
  }

  private c() {
    this.conn ??= DuckDBInstance.create("data/local.duckdb", { access_mode: "READ_ONLY" }).then((i) => i.connect());
    return this.conn;
  }

  async run(sql: string): Promise<QueryResult> {
    assertReadOnly(sql);
    const started = Date.now();
    const reader = await (await this.c()).runAndReadAll(sql);
    const columns = reader.columnNames();
    const rows = reader.getRowObjectsJson().map((r) =>
      Object.fromEntries(Object.entries(r).map(([k, v]) => [k.toLowerCase(), typeof v === "string" && /^-?\d+(\.\d+)?$/.test(v) ? Number(v) : v])),
    );
    return { columns, rows, ms: Date.now() - started };
  }

  async catalog() {
    const r = await this.run("SELECT table_name, string_agg(column_name, ',') AS cols FROM information_schema.columns GROUP BY 1 ORDER BY 1");
    return r.rows.map((x) => ({ table: String(x.table_name), columns: String(x.cols).split(",") }));
  }
}
